<h4>Applications</h4><form class="row g-2 mb-3"><div class="col-md-4"><input name="q" class="form-control" placeholder="Name, email or reference" value="<?= e($_GET['q']??'') ?>"></div>
<div class="col-md-3"><select name="status" class="form-select"><option value="">All statuses</option><?php foreach(['submitted','under_review','shortlisted','interview','accepted','rejected'] as $s): ?><option value="<?= $s ?>" <?= ($_GET['status']??'')===$s?'selected':'' ?>><?= ucwords(str_replace('_',' ',$s)) ?></option><?php endforeach; ?></select></div>
<div class="col-md-3"><select name="program" class="form-select"><option value="">All programs</option><?php foreach($progs as $p): ?><option value="<?= $p['id'] ?>" <?= ($_GET['program']??'')==$p['id']?'selected':'' ?>><?= e($p['code']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><button class="btn btn-primary w-100">Filter</button></div></form>
<table class="table bg-white shadow-sm"><tr><th>Ref</th><th>Applicant</th><th>Program</th><th>Merit</th><th>Status</th><th></th></tr>
<?php foreach($rows as $r): ?><tr><td><?= e($r['ref_no']) ?></td><td><?= e($r['name']) ?><br><small class="text-muted"><?= e($r['email']) ?></small></td><td><?= e($r['code']) ?></td><td><?= e($r['merit_score']) ?></td><td><?= badge($r['status']) ?></td><td><a href="<?= url('admin/applications/'.$r['id']) ?>">Review</a></td></tr><?php endforeach; ?></table>
